package com.example

/**
 * Complete, distinct 20 cards for Science Sets 11 to 15 (100 unique cards).
 * Covers Heat, Energy & Work, Reaction Rates, Light & Lenses, and Electricity & Magnetism.
 */
object FlashcardBankScienceSetsPart2 {

  fun getScienceSet(setNum: Int, cardNum: Int): CardContentTuple? {
    val c = cardNum.coerceIn(1, 20)
    return when (setNum) {
      11 -> scienceSet11[(c - 1) % scienceSet11.size]
      12 -> scienceSet12[(c - 1) % scienceSet12.size]
      13 -> scienceSet13[(c - 1) % scienceSet13.size]
      14 -> scienceSet14[(c - 1) % scienceSet14.size]
      15 -> scienceSet15[(c - 1) % scienceSet15.size]
      16 -> scienceSet16[(c - 1) % scienceSet16.size]
      17 -> scienceSet17[(c - 1) % scienceSet17.size]
      18 -> scienceSet18[(c - 1) % scienceSet18.size]
      19 -> scienceSet19[(c - 1) % scienceSet19.size]
      20 -> scienceSet20[(c - 1) % scienceSet20.size]
      else -> null
    }
  }

  // --- SET 11: තාපය, උෂ්ණත්වය & තාප සම්ප්‍රේෂණය ---
  private val scienceSet11 = listOf(
